def cache_sim(capacity, ttl, ops):
    cache = {}  # key -> (value, write_time)
    lru_order = []  # list of keys in order of most-recently-used to least-recently-used
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Remove expired entries from consideration
            cache_keys = list(cache.keys())
            for k in cache_keys:
                if cache[k][1] + ttl <= t:
                    del cache[k]
                    if k in lru_order:
                        lru_order.remove(k)

            # If key already exists, remove it from lru_order
            if key in cache:
                lru_order.remove(key)
            else:
                # Key is new. If cache is at capacity, evict LRU entry
                if len(cache) >= capacity:
                    lru_key = lru_order.pop()
                    del cache[lru_key]

            # Add the new/updated entry
            cache[key] = (value, t)
            lru_order.insert(0, key)  # Most recently used goes to front

        elif op[0] == 'get':
            _, t, key = op

            # Remove expired entries from consideration
            cache_keys = list(cache.keys())
            for k in cache_keys:
                if cache[k][1] + ttl <= t:
                    del cache[k]
                    if k in lru_order:
                        lru_order.remove(k)

            # Check if key exists and is not expired
            if key in cache:
                results.append(cache[key][0])
                # Move to front of lru_order (most recently used)
                lru_order.remove(key)
                lru_order.insert(0, key)
            else:
                results.append(-1)

    return results

